public protocol BackendRepositoryProtocol: AnyObject, Sendable {
    
    /**
     * Await cleanup of every admitted worker, including initialization and dropped callers.
     */
    func close() async 
    
    func diff(operationId: String, commitId: String, cancellation: BackendCancellation) async throws  -> [BackendChangedFile]
    
    func diffStatistics(operationId: String, commitId: String, cancellation: BackendCancellation) async throws  -> BackendDiffStatistics
    
    func fileDiff(operationId: String, commitId: String, filePath: String, cancellation: BackendCancellation) async throws  -> String
    
    func history(pageSize: UInt32, cancellation: BackendCancellation) async throws  -> BackendHistory
    
    func identity()  -> RepositoryIdentity
    
}
open class BackendRepository: BackendRepositoryProtocol, @unchecked Sendable {
    fileprivate let handle: UInt64

    /// Used to instantiate a [FFIObject] without an actual handle, for fakes in tests, mostly.
#if swift(>=5.8)
    @_documentation(visibility: private)
#endif
    public struct NoHandle {
        public init() {}
    }

    // TODO: We'd like this to be `private` but for Swifty reasons,
    // we can't implement `FfiConverter` without making this `required` and we can't
    // make it `required` without making it `public`.
#if swift(>=5.8)
    @_documentation(visibility: private)
#endif
    required public init(unsafeFromHandle handle: UInt64) {
        self.handle = handle
    }

    // This constructor can be used to instantiate a fake object.
    // - Parameter noHandle: Placeholder value so we can have a constructor separate from the default empty one that may be implemented for classes extending [FFIObject].
    //
    // - Warning:
    //     Any object instantiated with this constructor cannot be passed to an actual Rust-backed object. Since there isn't a backing handle the FFI lower functions will crash.
#if swift(>=5.8)
    @_documentation(visibility: private)
#endif
    public init(noHandle: NoHandle) {
        self.handle = 0
    }

#if swift(>=5.8)
    @_documentation(visibility: private)
#endif
    public func uniffiCloneHandle() -> UInt64 {
        return try! rustCall { uniffi_ravel_backend_fn_clone_backendrepository(self.handle, $0) }
    }
    // No primary constructor declared for this class.

    deinit {
        if handle == 0 {
            // Mock objects have handle=0 don't try to free them
            return
        }

        try! rustCall { uniffi_ravel_backend_fn_free_backendrepository(handle, $0) }
    }

    
